Future<List<WholesalePricingRow>> fetchWholesalePricingControl(int days) async{await requireAdminAccess();final r=await supabase.rpc('admin_list_wholesale_pricing_control',params:{'p_days':days,'p_limit':200});return (r as List).map((x)=>WholesalePricingRow.fromSupabase(Map<String,dynamic>.from(x as Map))).toList();}
